SELECT COUNT(*)
FROM ${table}
WHERE user_id = #{userId}

  AND ${pk} = #{alertId}


  AND status = #{status}

SELECT id, user_id, type, title, body, payload, status,
       created_at, delivered_at, seen_at
FROM ${table}
WHERE user_id = #{userId}

  AND ${pk} = #{alertId}


  AND status = #{status}

ORDER BY created_at DESC, ${pk} DESC
LIMIT #{limit} OFFSET #{offset}

