UPDATE ${table}
SET status = 'SENT',
    delivered_at = #{now}
WHERE ${pk} = #{id}
  AND user_id = #{userId}
  AND status = 'PENDING'

UPDATE ${table}
SET status = 'SEEN',
    seen_at = #{now}
WHERE ${pk} = #{id}
  AND user_id = #{userId}
  AND status IN ('PENDING','SENT')

UPDATE ${table}
SET status = 'SEEN',
    seen_at = #{now}
WHERE user_id = #{userId}
  AND status IN ('PENDING','SENT')
